            q: 'Should I take a machine learning course or a prompt engineering course?',
            a: 'It depends on what you want to do. A machine learning course teaches how models are built and trained — take it if you want to develop or fine-tune models. A prompt engineering course teaches how to get good, reliable output from existing models — take it if your work is using models rather than building them. If you only need better output day to day, the prompt engineering course delivers usable skill faster.',
