          '**여러분의 목적이 결정적인 제약 조건이며, 플랫폼 브랜드가 아닙니다.** 무료 기초 강좌와 유료 자격증은 서로 다른 목적을 위한 것입니다 — 이후에 달성하고자 하는 것에 맞게 범주를 선택한 다음 해당 범주 내에서 옵션을 비교하십시오.',
